// Version A
function computeOrderSummary(order: Order) {
  const total = order.items.reduce((s, i) => s + i.price * i.quantity, 0);
  const taxed = total * 1.08;
  return { total, taxed };
}

// Version B
function itemTotal(item: Item) {
  return item.price * item.quantity;
}

function computeOrderSummary(order: Order) {
  const total = order.items.reduce((s, i) => s + itemTotal(i), 0);
  const taxed = total * 1.08;
  return { total, taxed };
}
